SELECT id
FROM users u
WHERE u.username=#{username}
    AND u.password=#{password}

SELECT u.id, u.username, u.name, u.sex, u.tel, u.email, u.job, u.role, u.root, u.dept_id AS deptId, u.status, u.create_time AS createTime, u.doctor_id AS doctorId, d.dept_name AS deptName FROM users u LEFT JOIN dept d ON u.dept_id = d.id WHERE u.status != 4
AND u.name LIKE CONCAT('%', #{name}, '%')
ORDER BY u.id LIMIT #{start}, #{length}

mapper.update:
UPDATE users
name = #{name}, sex = #{sex}, tel = #{tel}, email = #{email}, job = #{job}, role = #{role}, root = #{root}, dept_id = #{deptId}, status = #{status},
WHERE id = #{id}
